Execution hierarchy: **Thread → Warp (32) → Block → Grid**

Built-in variables:
```cpp
threadIdx.x/y/z  // thread index within its block
blockIdx.x/y/z   // block index within the grid
blockDim.x/y/z   // threads per block
gridDim.x/y/z    // blocks in grid
warpSize         // always 32
```

Computing global thread IDs:
```cpp
// 1D
int tid = blockIdx.x * blockDim.x + threadIdx.x;

// 2D (matrices)
int row = blockIdx.y * blockDim.y + threadIdx.y;
int col = blockIdx.x * blockDim.x + threadIdx.x;
int idx = row * width + col;

// 3D (volumes)
int z = blockIdx.z * blockDim.z + threadIdx.z;
int y = blockIdx.y * blockDim.y + threadIdx.y;
int x = blockIdx.x * blockDim.x + threadIdx.x;
int idx3d = z * (width * height) + y * width + x;
```

```cpp
// Kernel launch: kernel<<<gridDim, blockDim, sharedMemBytes, stream>>>

// 1D launch for n elements
int threads = 256;
int blocks = (n + threads - 1) / threads;  // ceil division
kernel<<<blocks, threads>>>(d_data, n);

// 2D launch for W×H matrix
dim3 block(16, 16, 1);                      // 256 threads/block
dim3 grid((W + 15)/16, (H + 15)/16, 1);    // enough blocks for W×H
matrix_kernel<<<grid, block>>>(d_A, W, H);

// With shared memory
kernel<<<blocks, threads, shared_mem_bytes>>>(d_data, n);

// With stream
kernel<<<blocks, threads, 0, stream>>>(d_data, n);
```

Limits:
- Max threads per block: **1024**
- Max block dimensions: 1024 × 1024 × 64
- Warp size: always **32** (so use multiples of 32 for block size)

```cpp
// __global__ — kernel: called from host, runs on device
__global__ void myKernel(float* data, int n) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid < n) data[tid] *= 2.0f;
}

// __device__ — helper: called from device only
__device__ float square(float x) { return x * x; }

// __host__ — runs on host (default, explicit)
__host__ void cpuFunction() { /* ... */ }

// __host__ __device__ — runs on both
__host__ __device__ float add(float a, float b) { return a + b; }

// Optimization hints
__forceinline__ __device__ float fast_op(float x) { return x; }
__noinline__ __device__ void no_inline_op() { /* ... */ }
```

```cpp
// Allocate device memory
float *d_data;
cudaMalloc(&d_data, n * sizeof(float));

// Transfer: host → device
cudaMemcpy(d_data, h_data, n * sizeof(float), cudaMemcpyHostToDevice);

// Transfer: device → host
cudaMemcpy(h_data, d_data, n * sizeof(float), cudaMemcpyDeviceToHost);

// Zero out device memory
cudaMemset(d_data, 0, n * sizeof(float));

// Free device memory
cudaFree(d_data);

// Unified Memory (simpler, automatic migration)
float *data;
cudaMallocManaged(&data, n * sizeof(float));
// Use on host and device without explicit transfers!
cudaFree(data);

// Pinned host memory (faster transfers)
float *h_pinned;
cudaMallocHost(&h_pinned, n * sizeof(float));
cudaFreeHost(h_pinned);
```

```cpp
#include <cuda_runtime.h>
#include <stdio.h>

// Error checking macro
#define CUDA_CHECK(call) do { \
    cudaError_t err = call; \
    if (err != cudaSuccess) { \
        printf("CUDA error at %s:%d: %s\n", __FILE__, __LINE__, \
               cudaGetErrorString(err)); \
        exit(1); \
    } \
} while(0)

__global__ void vecAdd(const float* A, const float* B, float* C, int n) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid < n)   // bounds check!
        C[tid] = A[tid] + B[tid];
}

int main() {
    int n = 1024 * 1024;
    float *h_A = new float[n], *h_B = new float[n], *h_C = new float[n];

    float *d_A, *d_B, *d_C;
    CUDA_CHECK(cudaMalloc(&d_A, n * sizeof(float)));
    CUDA_CHECK(cudaMalloc(&d_B, n * sizeof(float)));
    CUDA_CHECK(cudaMalloc(&d_C, n * sizeof(float)));

    CUDA_CHECK(cudaMemcpy(d_A, h_A, n*sizeof(float), cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(d_B, h_B, n*sizeof(float), cudaMemcpyHostToDevice));

    int threads = 256;
    int blocks = (n + threads - 1) / threads;
    vecAdd<<<blocks, threads>>>(d_A, d_B, d_C, n);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());

    CUDA_CHECK(cudaMemcpy(h_C, d_C, n*sizeof(float), cudaMemcpyDeviceToHost));

    cudaFree(d_A); cudaFree(d_B); cudaFree(d_C);
    delete[] h_A; delete[] h_B; delete[] h_C;
}
```

```cpp
#define TILE 16

__global__ void tiledMatMul(const float* A, const float* B, float* C,
                             int M, int N, int K) {
    // Tiles in shared memory — fast!
    __shared__ float tileA[TILE][TILE];
    __shared__ float tileB[TILE][TILE];

    int row = blockIdx.y * TILE + threadIdx.y;
    int col = blockIdx.x * TILE + threadIdx.x;
    float sum = 0.0f;

    for (int t = 0; t < (K + TILE - 1) / TILE; t++) {
        // Load tiles from global → shared memory
        tileA[threadIdx.y][threadIdx.x] =
            (row < M && t*TILE + threadIdx.x < K)
            ? A[row * K + t*TILE + threadIdx.x] : 0;
        tileB[threadIdx.y][threadIdx.x] =
            (t*TILE + threadIdx.y < K && col < N)
            ? B[(t*TILE + threadIdx.y) * N + col] : 0;

        __syncthreads();  // wait for ALL threads to finish loading

        for (int k = 0; k < TILE; k++)
            sum += tileA[threadIdx.y][k] * tileB[k][threadIdx.x];

        __syncthreads();  // wait before loading next tile
    }
    if (row < M && col < N) C[row * N + col] = sum;
}
```

Each tile is loaded from slow global memory ONCE, then all threads in the block reuse it from fast shared memory.

```cpp
// Default stream — everything serialized
kernel<<<blocks, threads>>>(d_data, n);  // stream 0

// Named streams — can overlap with each other
cudaStream_t stream1, stream2;
cudaStreamCreate(&stream1);
cudaStreamCreate(&stream2);

// Async transfers + kernels in separate streams
cudaMemcpyAsync(d_A, h_A, size, cudaMemcpyHostToDevice, stream1);
cudaMemcpyAsync(d_B, h_B, size, cudaMemcpyHostToDevice, stream2);

kernel1<<<blocks, threads, 0, stream1>>>(d_A, n);
kernel2<<<blocks, threads, 0, stream2>>>(d_B, n);

// Wait for all streams to finish
cudaStreamSynchronize(stream1);
cudaStreamSynchronize(stream2);
cudaDeviceSynchronize();  // or wait for everything

cudaStreamDestroy(stream1);
cudaStreamDestroy(stream2);
```

Streams enable **overlapping**: transfer data for batch 2 while computing batch 1 → significant throughput improvement.

```cpp
// Parallel reduction using shared memory
__global__ void reduce_sum(const float* in, float* out, int n) {
    extern __shared__ float sdata[];  // dynamic shared memory
    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    sdata[tid] = (idx < n) ? in[idx] : 0;
    __syncthreads();

    // Reduction tree
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) sdata[tid] += sdata[tid + s];
        __syncthreads();
    }
    if (tid == 0) atomicAdd(out, sdata[0]);  // atomic write to global
}

// Launch with dynamic shared memory
reduce_sum<<<blocks, 256, 256*sizeof(float)>>>(d_in, d_out, n);

// Atomic operations
atomicAdd(&counter, 1);
atomicMax(&max_val, val);
atomicCAS(&lock, 0, 1);  // compare-and-swap
```

The reduction tree halves the work at each step: O(n) work with O(log n) depth.

```cpp
// Warp-level synchronization
__syncwarp();                     // sync all 32 threads in warp
__syncwarp(0xFFFFFFFF);           // sync specific mask of threads

// __ballot_sync — get bitmask of which threads satisfy a predicate
unsigned mask = __ballot_sync(0xFFFFFFFF, value > 0);
int count = __popc(mask);         // count of true threads

// Warp shuffle — exchange values without shared memory
float val = threadIdx.x * 1.0f;
// All threads get value from lane 0
float broadcast = __shfl_sync(0xFFFFFFFF, val, 0);
// Get value from lane (tid + 1) % 32
float next = __shfl_down_sync(0xFFFFFFFF, val, 1);

// Warp-level reduction (very fast)
for (int offset = 16; offset > 0; offset >>= 1)
    val += __shfl_down_sync(0xFFFFFFFF, val, offset);
// lane 0 now holds the sum
```

Warp-level primitives avoid shared memory and `__syncthreads()` overhead within a warp.

Coalesced access: when consecutive threads (tid 0, 1, 2, ...) access consecutive memory addresses simultaneously — the hardware combines them into a single wide memory transaction.

```cpp
// COALESCED — 32 threads access 32 consecutive floats → 1 transaction
__global__ void coalesced(float* data, int n) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid < n) data[tid] *= 2.0f;   // tid+0 → data[0], tid+1 → data[1]...
}

// UN-COALESCED — strided access → 32 separate transactions (32× slower!)
__global__ void strided(float* data, int n, int stride) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid < n) data[tid * stride] *= 2.0f;  // scattered addresses
}
```

For matrix operations:
- **Row-major access by row** → coalesced (C is row-major)
- **Column access** → strided, uncoalesced → transpose the matrix or use shared memory as a transposing buffer

```cpp
#include <cublas_v2.h>

cublasHandle_t handle;
cublasCreate(&handle);

float alpha = 1.0f, beta = 0.0f;

// C = alpha * A * B + beta * C
// cublasSgemm computes column-major, so we swap A and B for row-major
cublasSgemm(handle,
    CUBLAS_OP_N, CUBLAS_OP_N,
    N, M, K,         // dimensions of result and inner
    &alpha,
    d_B, N,          // matrix B (swapped for row-major)
    d_A, K,          // matrix A
    &beta,
    d_C, N);         // result C

cublasDestroy(handle);
```

cuBLAS is **highly optimized** — typically 10-100× faster than a naive kernel. Always use cuBLAS (or cuDNN for deep learning) instead of writing your own GEMM.

```cpp
// Unified Memory — single pointer usable on both CPU and GPU
float *data;
cudaMallocManaged(&data, n * sizeof(float));

// Initialize on CPU
for (int i = 0; i < n; i++) data[i] = i;

// Use on GPU — pages migrate automatically
kernel<<<blocks, threads>>>(data, n);
cudaDeviceSynchronize();

// Read on CPU — pages migrate back
printf("data[0] = %f\n", data[0]);

cudaFree(data);

// Prefetch hint (Volta+)
cudaMemPrefetchAsync(data, n*sizeof(float), cudaCpuDeviceId);
cudaMemPrefetchAsync(data, n*sizeof(float), device_id);
```

**Use when**: prototyping, data structures with complex pointers (graphs, trees), or when migration overhead is acceptable.

**Don't use when**: maximum performance is critical — explicit `cudaMemcpy` with pinned memory + streams is faster.
